const moveQueuedBacklogInputToFront = `-- name: MoveQueuedBacklogInputToFront :execrows
WITH first_neighbor AS (
  SELECT input_rank
  FROM agent_inputs
  WHERE project_id = $1
    AND agent_id = $2
    AND state = 'received'
    AND delivery_mode = 'queued'
    AND input_kind = 'content'
    AND id <> $3
  ORDER BY input_rank ASC, queued_at ASC, id ASC
  LIMIT 1
),
new_rank AS (
  SELECT CASE
    WHEN (SELECT input_rank FROM first_neighbor) IS NULL THEN $4::bigint
    WHEN (SELECT input_rank FROM first_neighbor) > 1 THEN
      (SELECT input_rank / 2 FROM first_neighbor)
    ELSE NULL::bigint
  END AS input_rank
)
UPDATE agent_inputs input
SET input_rank = new_rank.input_rank
FROM new_rank
WHERE input.project_id = $1
  AND input.agent_id = $2
  AND input.id = $3
  AND input.state = 'received'
  AND input.delivery_mode = 'queued'
  AND input.input_kind = 'content'
  AND new_rank.input_rank IS NOT NULL
`

type MoveQueuedBacklogInputToFrontParams struct {
	ProjectID  uuid.UUID
	AgentID    uuid.UUID
	ID         uuid.UUID
	RankStride int64
}

func (q *Queries) MoveQueuedBacklogInputToFront(ctx context.Context, arg MoveQueuedBacklogInputToFrontParams) (int64, error) {
	result, err := q.db.Exec(ctx, moveQueuedBacklogInputToFront,
		arg.ProjectID,
		arg.AgentID,
		arg.ID,
		arg.RankStride,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const promoteQueuedInputToSteering = `-- name: PromoteQueuedInputToSteering :one
WITH promoted AS (
  UPDATE agent_inputs input
  SET delivery_mode = 'steering',
      input_rank = coalesce(
        (
          SELECT max(existing.input_rank) + $4::bigint
          FROM agent_inputs existing
          WHERE existing.project_id = input.project_id
            AND existing.agent_id = input.agent_id
            AND existing.delivery_mode = 'steering'
            AND existing.state = 'received'
            AND existing.input_kind = 'content'
        ),
        $4::bigint
      )
  WHERE input.project_id = $1
    AND input.agent_id = $2
    AND input.id = $3
    AND input.state = 'received'
    AND input.delivery_mode = 'queued'
    AND input.input_kind = 'content'
  RETURNING TRUE
)
SELECT EXISTS (SELECT 1 FROM promoted) AS changed,
       EXISTS (SELECT 1 FROM promoted)
       OR EXISTS (
         SELECT 1
         FROM agent_inputs input
         WHERE input.project_id = $1
           AND input.agent_id = $2
           AND input.id = $3
           AND input.input_kind = 'content'
           AND (
             (input.state = 'received' AND input.delivery_mode = 'steering')
             OR (input.state = 'resolved' AND input.admitted_event_id IS NOT NULL)
           )
       ) AS effective
`

type PromoteQueuedInputToSteeringParams struct {
	ProjectID  uuid.UUID
	AgentID    uuid.UUID
	ID         uuid.UUID
	RankStride int64
}

type PromoteQueuedInputToSteeringRow struct {
	Changed   bool
	Effective *bool
}

func (q *Queries) PromoteQueuedInputToSteering(ctx context.Context, arg PromoteQueuedInputToSteeringParams) (PromoteQueuedInputToSteeringRow, error) {
	row := q.db.QueryRow(ctx, promoteQueuedInputToSteering,
		arg.ProjectID,
		arg.AgentID,
		arg.ID,
		arg.RankStride,
	)
	var i PromoteQueuedInputToSteeringRow
	err := row.Scan(&i.Changed, &i.Effective)
	return i, err
}

const queuedBacklogMoveIsValid = `-- name: QueuedBacklogMoveIsValid :one
SELECT CASE WHEN EXISTS (
  SELECT 1
  FROM agent_inputs input
  WHERE input.project_id = $1
    AND input.agent_id = $2
    AND input.id = $3
    AND input.state = 'received'
    AND input.delivery_mode = 'queued'
    AND input.input_kind = 'content'
) AND (
  NOT $4::boolean
  OR EXISTS (
    SELECT 1
    FROM agent_inputs anchor
    WHERE anchor.project_id = $1
      AND anchor.agent_id = $2
      AND anchor.id = $5
      AND anchor.state = 'received'
      AND anchor.delivery_mode = 'queued'
      AND anchor.input_kind = 'content'
  )
) THEN true ELSE false END AS valid
`

type QueuedBacklogMoveIsValidParams struct {
	ProjectID      uuid.UUID
	AgentID        uuid.UUID
	ID             uuid.UUID
	RequiresAnchor bool
	AnchorID       uuid.UUID
}

func (q *Queries) QueuedBacklogMoveIsValid(ctx context.Context, arg QueuedBacklogMoveIsValidParams) (bool, error) {
	row := q.db.QueryRow(ctx, queuedBacklogMoveIsValid,
		arg.ProjectID,
		arg.AgentID,
		arg.ID,
		arg.RequiresAnchor,
		arg.AnchorID,
	)
	var valid bool
	err := row.Scan(&valid)
	return valid, err
}

const rebalanceQueuedBacklogRanks = `-- name: RebalanceQueuedBacklogRanks :execrows
WITH ordered AS (
  SELECT id, row_number() OVER (ORDER BY input_rank ASC, queued_at ASC, id ASC) AS row_number
  FROM agent_inputs
  WHERE project_id = $2
    AND agent_id = $3
    AND state = 'received'
    AND delivery_mode = 'queued'
    AND input_kind = 'content'
)
UPDATE agent_inputs input
SET input_rank = ordered.row_number * $1::bigint
FROM ordered
WHERE input.project_id = $2
  AND input.agent_id = $3
  AND input.id = ordered.id
`

type RebalanceQueuedBacklogRanksParams struct {
	RankStride int64
	ProjectID  uuid.UUID
	AgentID    uuid.UUID
}

func (q *Queries) RebalanceQueuedBacklogRanks(ctx context.Context, arg RebalanceQueuedBacklogRanksParams) (int64, error) {
	result, err := q.db.Exec(ctx, rebalanceQueuedBacklogRanks, arg.RankStride, arg.ProjectID, arg.AgentID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const rebuildMissingAgentWakeupsBatch = `-- name: RebuildMissingAgentWakeupsBatch :many
WITH locked_agents AS MATERIALIZED (
  SELECT agent.id, agent.project_id
  FROM agents agent
  WHERE agent.project_id = $1
    AND agent.state <> 'archived'
    AND (
      $2::uuid IS NULL
      OR agent.id > $2::uuid
    )
    AND NOT EXISTS (
      SELECT 1
      FROM agent_wakeups wake
      WHERE wake.agent_id = agent.id
    )
  ORDER BY agent.id
  LIMIT $3
  FOR UPDATE OF agent SKIP LOCKED
),
desired AS MATERIALIZED (
  SELECT agent.id,
         agent.project_id,
         agent_next_wakeup_ready_at(
           agent.project_id,
           agent.id
         ) AS ready_at
  FROM locked_agents agent
  WHERE NOT EXISTS (
    SELECT 1
    FROM agent_runtime_locks runtime_lock
    WHERE runtime_lock.agent_id = agent.id
  )
),
inserted AS (
  INSERT INTO agent_wakeups(agent_id, ready_at, updated_at, metadata)
  SELECT desired.id,
         desired.ready_at,
         statement_timestamp(),
         $4
  FROM desired
  WHERE desired.ready_at IS NOT NULL
  ON CONFLICT (agent_id) DO NOTHING
  RETURNING agent_id
)
SELECT locked.id AS agent_id,
       (inserted.agent_id IS NOT NULL)::boolean AS inserted
FROM locked_agents locked
LEFT JOIN inserted ON inserted.agent_id = locked.id
ORDER BY locked.id
`

type RebuildMissingAgentWakeupsBatchParams struct {
	ProjectID    uuid.UUID
	AfterAgentID *uuid.UUID
	BatchLimit   int32
	Metadata     json.RawMessage
}

type RebuildMissingAgentWakeupsBatchRow struct {
	AgentID  uuid.UUID
	Inserted bool
}

func (q *Queries) RebuildMissingAgentWakeupsBatch(ctx context.Context, arg RebuildMissingAgentWakeupsBatchParams) ([]RebuildMissingAgentWakeupsBatchRow, error) {
	rows, err := q.db.Query(ctx, rebuildMissingAgentWakeupsBatch,
		arg.ProjectID,
		arg.AfterAgentID,
		arg.BatchLimit,
		arg.Metadata,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RebuildMissingAgentWakeupsBatchRow{}
	for rows.Next() {
		var i RebuildMissingAgentWakeupsBatchRow
		if err := rows.Scan(&i.AgentID, &i.Inserted); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reconcileAgentWakeup = `-- name: ReconcileAgentWakeup :exec
WITH locked_agent AS MATERIALIZED (
  SELECT agent.id, agent.project_id
  FROM agents agent
  WHERE agent.project_id = $1
    AND agent.id = $2
    AND agent.state <> 'archived'
),
desired AS MATERIALIZED (
  SELECT agent_next_wakeup_ready_at(
    locked_agent.project_id,
    locked_agent.id
  ) AS ready_at
  FROM locked_agent
),
upserted AS (
  INSERT INTO agent_wakeups(agent_id, ready_at, updated_at, metadata)
  SELECT locked_agent.id,
         desired.ready_at,
         statement_timestamp(),
         $3
  FROM locked_agent
  JOIN desired ON desired.ready_at IS NOT NULL
  ON CONFLICT (agent_id) DO UPDATE
  SET ready_at = excluded.ready_at,
      updated_at = GREATEST(agent_wakeups.updated_at, excluded.updated_at),
      metadata = agent_wakeups.metadata || excluded.metadata
  RETURNING agent_id
)
DELETE FROM agent_wakeups wake
USING locked_agent
CROSS JOIN desired
WHERE wake.agent_id = locked_agent.id
  AND desired.ready_at IS NULL
`

type ReconcileAgentWakeupParams struct {
	ProjectID uuid.UUID
	AgentID   uuid.UUID
	Metadata  json.RawMessage
}

func (q *Queries) ReconcileAgentWakeup(ctx context.Context, arg ReconcileAgentWakeupParams) error {
	_, err := q.db.Exec(ctx, reconcileAgentWakeup, arg.ProjectID, arg.AgentID, arg.Metadata)
	return err
}
